      ctx.fillStyle = '#a81c34'; ctx.beginPath(); ctx.moveTo(x + 4, 3); ctx.lineTo(x + w - 4, 3); ctx.quadraticCurveTo(x + w / 2, 21, x + 4, 3); ctx.fill();
