// ---------------------------------------------------------------- challenge room (world pass): a film-leader door in one Dot's secret leads to a short bonus room off the right edge of the map
{
  const CH = { OLDW: 236 };   // the main map ends at this tile column; the room lives to the right of it
  DD.defineEntity('cdoor', {   // a door: press Down in it to cross (to the room and back). args: destination tile x, destination row (feet)
    spawn: t => ({ x: t.x + 1, y: t.y + 16 - (t.args[2] || 30), w: 14, h: t.args[2] || 30, dx: t.args[0], dr: t.args[1], t: 0, inside: true }),
    update(e, G) {
      e.t++;
      const p = G.pl, inside = DD.ov(p, e);
      if (G.frame >= (G.cdUntil || 0) && DD.door(e)) {   // press Down in the doorway to cross
        G.cdUntil = G.frame + 45; G.hitstop = 8;
        DD.stars(DD.cx(p), p.y + 6, 10, '#ffd24a'); DD.SFX.cp && DD.SFX.cp();
        p.x = e.dx * 16 + 2; p.y = (e.dr + 1) * 16 - p.h - 1; p.vx = 0; p.vy = 0; p.slam = 0; p.inv = Math.max(p.inv || 0, 20);
        G.safe = { x: p.x, y: p.y }; G.cpSafe = { x: p.x, y: p.y };
        G.cam.x = DD.clamp(p.x - 160, 0, LEVEL.W * 16 - 320); G.cam.y = DD.clamp(p.y + p.h - 112, 0, LEVEL.H * 16 - 180);
        DD.stars(DD.cx(p), p.y + 6, 10, '#ffd24a');
      }
      e.inside = inside;
    },
    stomp: () => false,
    touch: () => {},
    draw(e, ctx) {
      const X = DD.wx(e.x), Y = DD.wy(e.y), f = e.t, pul = 0.5 + 0.5 * Math.sin(f / 10);
      if (e.h < 20) {   // a hatch for a one-tile crawl
        ctx.fillStyle = 'rgba(255,210,74,' + (0.12 + 0.12 * pul) + ')'; ctx.fillRect(X - 3, Y - 3, 20, 20);
        ctx.fillStyle = '#1a1020'; ctx.fillRect(X - 1, Y - 1, 16, 16); ctx.fillStyle = '#ffd24a'; ctx.fillRect(X + 1, Y + 1, 12, 12);
        ctx.fillStyle = '#7a3a10'; ctx.fillRect(X + 1, Y + 1, 12, 2); ctx.fillRect(X + 1, Y + 11, 12, 2);
        ctx.fillStyle = '#fff6c0'; const cx = X + 4 + Math.round(pul * 3); ctx.beginPath(); ctx.moveTo(cx, Y + 4); ctx.lineTo(cx + 4, Y + 7); ctx.lineTo(cx, Y + 10); ctx.fill();
        return;
      }
      ctx.fillStyle = 'rgba(255,210,74,' + (0.10 + 0.10 * pul) + ')'; ctx.fillRect(X - 5, Y - 4, 24, 38);
      ctx.fillStyle = '#1a1020'; ctx.fillRect(X - 1, Y - 2, 16, 32);
      ctx.fillStyle = '#ffd24a'; ctx.fillRect(X + 1, Y, 12, 30);
      ctx.fillStyle = '#7a3a10'; ctx.fillRect(X + 1, Y, 2, 30); ctx.fillRect(X + 11, Y, 2, 30);
      ctx.fillStyle = '#1a1020'; for (let i = 0; i < 5; i++) { ctx.fillRect(X + 1, Y + 2 + i * 6, 2, 3); ctx.fillRect(X + 11, Y + 2 + i * 6, 2, 3); }
      ctx.fillStyle = '#fff6c0'; const cy = Y + 8 + Math.round(pul * 6); ctx.beginPath(); ctx.moveTo(X + 5, cy); ctx.lineTo(X + 9, cy + 4); ctx.lineTo(X + 5, cy + 8); ctx.fill();
    },
  });
  const prevCam = LEVEL.script && LEVEL.script.camera;   // keep the camera inside the main map, or inside the room
  LEVEL.script = LEVEL.script || {};
  LEVEL.script.camera = function (G, c, snap) {
    if (prevCam) prevCam.call(this, G, c, snap);
    const X0 = CH.OLDW * 16;
    if (G.pl.x < X0) c.x = Math.min(c.x, X0 - 320); else c.x = Math.max(c.x, X0);
  };
}

// ---------------------------------------------------------------- world 12 enemy (world pass): the Hav-A-Scoop server
{
  DD.defineEntity('scoophop', {   // a Hav-A-Scoop server, visibly bored, a tuna-salad cone in hand: crouches for half a second (the warning), then lunges at you; stomp them for 2 (kind kept as scoophop)
    spawn: t => ({ x: t.x + 2, y: t.y, w: 12, h: 16, vx: 0, vy: 0, mode: 0, t: (t.tx * 11) % 60, dir: -1, sq: 0 }),
    update(e, G) {
      e.t++;
      const near = Math.abs(DD.cx(G.pl) - DD.cx(e)) < 16 * 9;
      e.vy = Math.min(e.vy + 0.4, 6); const landed = DD.moveY(e, e.vy, false); if (landed) { if (e.mode === 2) { e.mode = 0; e.t = 0; e.vx = 0; } e.vy = 0; }
      if (e.mode === 0 && e.t > 60 && near) { e.mode = 1; e.t = 0; e.dir = DD.cx(G.pl) < DD.cx(e) ? -1 : 1; }
      else if (e.mode === 1) { e.sq = Math.min(1, e.t / 28); if (e.t >= 32) { e.mode = 2; e.t = 0; e.vy = -5.4; e.vx = e.dir * 1.5; e.sq = 0; } }
      if (e.mode === 2) { if (DD.moveX(e, e.vx, false)) e.vx = -e.vx; }
    },
    stomp(e) { e.dead = true; DD.addGot(2, DD.cx(e), e.y); DD.SFX.stomp && DD.SFX.stomp(); DD.stars(DD.cx(e), e.y + 8, 6, '#9ad8ff'); DD.dust(DD.cx(e), e.y + 14, 6, 1.4, '#e8e0c8'); return true; },
    touch(e) { DD.hurt(DD.cx(e)); },
    draw(e, ctx) {
      const X = DD.wx(e.x + e.w / 2), Y = DD.wy(e.y + e.h), sy = 1 - 0.25 * e.sq, sx = 1 + 0.15 * e.sq, air = e.mode === 2;
      ctx.fillStyle = 'rgba(0,0,0,0.25)'; ctx.beginPath(); ctx.ellipse(X, Y - 1, air ? 4 : 6, 1.5, 0, 0, 7); ctx.fill();
      DD.spr('w12_scoophop_' + (air ? 2 : e.mode === 1 && e.sq > 0.4 ? 1 : 0), X, Y, e.dir > 0, sx, e.mode === 1 ? 1 : sy);   // charpass: the sprite
      if (e.mode === 1 && Math.floor(e.t / 5) % 2) { ctx.fillStyle = '#ffffff'; ctx.fillRect(X - 1, Y - 26, 2, 5); ctx.fillRect(X - 1, Y - 19, 2, 2); }   // a flicker over the head before the lunge
    },
  });
}
